#include <stdio.h>
#include <stdlib.h>

typedef struct {
    double w, v;
} Item;

static int cmp(const void *a, const void *b) {
    const Item *x = (const Item *)a;
    const Item *y = (const Item *)b;

    /* Handle zero-weight items first if they have positive value density */
    if (x->w == 0.0 && y->w == 0.0) {
        if (x->v > y->v) return -1;
        if (x->v < y->v) return 1;
        return 0;
    }
    if (x->w == 0.0) return (x->v >= 0.0 ? -1 : 1);
    if (y->w == 0.0) return (y->v >= 0.0 ? 1 : -1);

    double lhs = x->v / x->w;
    double rhs = y->v / y->w;
    if (lhs > rhs) return -1;
    if (lhs < rhs) return 1;
    return 0;
}

int main(void) {
    int N;
    double W;

    if (scanf("%d %lf", &N, &W) != 2) return 0;

    Item *a = (Item *)malloc(sizeof(Item) * N);
    if (!a) return 0;

    for (int i = 0; i < N; i++) {
        scanf("%lf %lf", &a[i].w, &a[i].v);
    }

    qsort(a, N, sizeof(Item), cmp);

    double ans = 0.0;
    double rem = W;

    for (int i = 0; i < N; i++) {
        if (a[i].w == 0.0) {
            if (a[i].v > 0.0) ans += a[i].v; /* can take fully for free */
            continue;
        }
        if (rem <= 0.0) break;
        if (a[i].v <= 0.0) break; /* no benefit taking non-positive density items */

        double take = rem < a[i].w ? rem : a[i].w;
        ans += (a[i].v / a[i].w) * take;
        rem -= take;
    }

    printf("%.10f\n", ans);

    free(a);
    return 0;
}

