public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        double W = Double.parseDouble(st.nextToken());

        double[] v = new double[N];
        double[] w = new double[N];

        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            v[i] = Double.parseDouble(st.nextToken());
            w[i] = Double.parseDouble(st.nextToken());
        }

        // Sort by value/weight ratio descending
        Integer[] idx = new Integer[N];
        for (int i = 0; i < N; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> {
            // Handle w=0 cases
            double ra = (w[a] == 0) ? Double.MAX_VALUE : v[a] / w[a];
            double rb = (w[b] == 0) ? Double.MAX_VALUE : v[b] / w[b];
            return Double.compare(rb, ra);
        });

        double totalValue = 0;
        double remainingWeight = W;

        for (int i = 0; i < N; i++) {
            int item = idx[i];
            if (w[item] == 0) {
                // Take it fully (v >= 0)
                totalValue += v[item];
            } else if (remainingWeight >= w[item]) {
                totalValue += v[item];
                remainingWeight -= w[item];
            } else {
                totalValue += v[item] * (remainingWeight / w[item]);
                remainingWeight = 0;
                break;
            }
        }

        System.out.printf("%.10f%n", totalValue);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class Item {
        double w, v;
        Item(double w, double v) {
            this.w = w;
            this.v = v;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        double W = fs.nextDouble();

        Item[] items = new Item[N];
        for (int i = 0; i < N; i++) {
            double w = fs.nextDouble();
            double v = fs.nextDouble();
            items[i] = new Item(w, v);
        }

        Arrays.sort(items, (a, b) -> {
            double ra = a.v / a.w;
            double rb = b.v / b.w;
            return Double.compare(rb, ra);
        });

        double ans = 0.0;
        double remain = W;

        for (Item it : items) {
            if (remain <= 0) break;
            double take = Math.min(1.0, remain / it.w);
            ans += it.v * take;
            remain -= it.w * take;
        }

        System.out.printf(Locale.US, "%.10f%n", ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && Character.isWhitespace(c));
            if (c == -1) return null;
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}
